'use client'
import { useState, useEffect } from 'react'
import Link from 'next/link'
import { FileText } from 'lucide-react'

export default function AdminOrders() {
  const [orders, setOrders] = useState([])
  const [loading, setLoading] = useState(true)
  const [updatingId, setUpdatingId] = useState(null)

  useEffect(() => {
    fetchOrders()
  }, [])

  const fetchOrders = async () => {
    setLoading(true)
    const res = await fetch('/api/orders')
    const data = await res.json()
    setOrders(data)
    setLoading(false)
  }

  const handleStatusChange = async (id, newStatus) => {
    setUpdatingId(id)
    await fetch(`/api/orders/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: newStatus })
    })
    setUpdatingId(null)
    fetchOrders()
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-extrabold">Manage Orders</h1>
      </div>

      {loading ? (
        <div className="text-center text-muted-foreground animate-pulse p-10">Loading orders...</div>
      ) : (
        <div className="bg-background rounded-2xl border overflow-hidden shadow-sm">
          <table className="w-full text-left border-collapse">
             <thead>
               <tr className="bg-secondary text-muted-foreground text-sm uppercase tracking-wider">
                 <th className="p-4 font-semibold">Order ID</th>
                 <th className="p-4 font-semibold">Customer</th>
                 <th className="p-4 font-semibold">Total</th>
                 <th className="p-4 font-semibold">Status</th>
                 <th className="p-4 font-semibold text-right">Actions</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-border">
               {orders.map(o => (
                 <tr key={o._id} className="hover:bg-secondary/30 transition-colors">
                   <td className="p-4 font-mono text-sm">#{o._id.slice(-8).toUpperCase()}</td>
                   <td className="p-4">
                     <div className="font-semibold">{o.userId?.name}</div>
                     <div className="text-sm text-muted-foreground">{o.userId?.email}</div>
                   </td>
                   <td className="p-4 font-bold text-foreground">
                     ${o.totalPrice.toFixed(2)}
                   </td>
                   <td className="p-4">
                     <select 
                       value={o.status}
                       disabled={updatingId === o._id}
                       onChange={(e) => handleStatusChange(o._id, e.target.value)}
                       className={`p-2 rounded-lg text-sm font-semibold uppercase tracking-wider outline-none border cursor-pointer
                         ${o.status === 'delivered' ? 'bg-green-100 text-green-700 border-green-200' : 
                           o.status === 'shipped' ? 'bg-blue-100 text-blue-700 border-blue-200' : 
                           'bg-yellow-100 text-yellow-700 border-yellow-200'}
                       `}
                     >
                       <option value="pending">Pending</option>
                       <option value="shipped">Shipped</option>
                       <option value="delivered">Delivered</option>
                     </select>
                   </td>
                   <td className="p-4 flex gap-2 justify-end">
                      <Link href={`/invoice/${o._id}`} className="text-sm font-medium flex items-center gap-1.5 px-3 py-2 bg-secondary rounded-lg hover:bg-border transition-colors">
                        <FileText className="w-4 h-4"/> Invoice
                      </Link>
                   </td>
                 </tr>
               ))}
               {orders.length === 0 && (
                 <tr><td colSpan="5" className="p-8 text-center text-muted-foreground">No orders found.</td></tr>
               )}
             </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

'use client'
import { useState, useEffect } from 'react'
import { Edit, Trash2, Plus } from 'lucide-react'

export default function AdminProducts() {
  const [products, setProducts] = useState([])
  const [loading, setLoading] = useState(true)
  const [formData, setFormData] = useState({ name: '', description: '', price: '', discountPrice: '', imageUrl: '', category: '' })
  const [editId, setEditId] = useState(null)

  useEffect(() => {
    fetchProducts()
  }, [])

  const fetchProducts = async () => {
    setLoading(true)
    const res = await fetch('/api/products')
    const data = await res.json()
    setProducts(data)
    setLoading(false)
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    const url = editId ? `/api/products/${editId}` : '/api/products'
    const method = editId ? 'PUT' : 'POST'

    // cast numbers
    const payload = { ...formData, price: Number(formData.price) }
    if (formData.discountPrice) payload.discountPrice = Number(formData.discountPrice)

    await fetch(url, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    })

    setFormData({ name: '', description: '', price: '', discountPrice: '', imageUrl: '', category: '' })
    setEditId(null)
    fetchProducts()
  }

  const handleDelete = async (id) => {
    if (!confirm('Are you sure you want to delete this product?')) return
    await fetch(`/api/products/${id}`, { method: 'DELETE' })
    fetchProducts()
  }

  const handleEdit = (product) => {
    setEditId(product._id)
    setFormData({
      name: product.name,
      description: product.description,
      price: product.price,
      discountPrice: product.discountPrice || '',
      imageUrl: product.imageUrl || '',
      category: product.category
    })
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-extrabold">Manage Products</h1>
      </div>

      <form onSubmit={handleSubmit} className="bg-background p-6 rounded-2xl border space-y-4 shadow-sm">
        <h2 className="font-bold text-lg">{editId ? 'Edit Product' : 'Add New Product'}</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <input required type="text" placeholder="Name" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="p-3 border rounded-xl bg-secondary/50 focus:bg-background outline-none focus:ring-2 focus:ring-primary/50" />
          <input required type="text" placeholder="Category" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="p-3 border rounded-xl bg-secondary/50 focus:bg-background outline-none focus:ring-2 focus:ring-primary/50" />
          <input required type="number" step="0.01" placeholder="Price" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} className="p-3 border rounded-xl bg-secondary/50 focus:bg-background outline-none focus:ring-2 focus:ring-primary/50" />
          <input type="number" step="0.01" placeholder="Discount Price (Optional)" value={formData.discountPrice} onChange={e => setFormData({...formData, discountPrice: e.target.value})} className="p-3 border rounded-xl bg-secondary/50 focus:bg-background outline-none focus:ring-2 focus:ring-primary/50" />
        </div>
        <input type="text" placeholder="Image URL (Optional)" value={formData.imageUrl} onChange={e => setFormData({...formData, imageUrl: e.target.value})} className="w-full p-3 border rounded-xl bg-secondary/50 focus:bg-background outline-none focus:ring-2 focus:ring-primary/50" />
        <textarea required placeholder="Description" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full p-3 border rounded-xl bg-secondary/50 focus:bg-background outline-none focus:ring-2 focus:ring-primary/50 h-24" />

        <div className="flex gap-2">
          <button type="submit" className="bg-primary text-primary-foreground px-6 py-2 rounded-xl font-bold hover:bg-primary/90 flex items-center gap-2">
            {editId ? 'Update Product' : <><Plus className="w-4 h-4"/> Add Product</>}
          </button>
          {editId && (
             <button type="button" onClick={() => { setEditId(null); setFormData({ name: '', description: '', price: '', discountPrice: '', imageUrl: '', category: '' }) }} className="bg-secondary text-secondary-foreground px-6 py-2 rounded-xl font-bold hover:bg-secondary/80">
               Cancel
             </button>
          )}
        </div>
      </form>

      {loading ? (
        <div className="text-center text-muted-foreground animate-pulse p-10">Loading products...</div>
      ) : (
        <div className="bg-background rounded-2xl border overflow-hidden shadow-sm">
          <table className="w-full text-left border-collapse">
             <thead>
               <tr className="bg-secondary text-muted-foreground text-sm uppercase tracking-wider">
                 <th className="p-4 font-semibold">Product</th>
                 <th className="p-4 font-semibold">Category</th>
                 <th className="p-4 font-semibold">Price</th>
                 <th className="p-4 font-semibold text-right">Actions</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-border">
               {products.map(p => (
                 <tr key={p._id} className="hover:bg-secondary/30 transition-colors">
                   <td className="p-4 font-medium flex items-center gap-3">
                     {p.imageUrl ? (
                       <img src={p.imageUrl} alt={p.name} className="w-10 h-10 rounded-md object-cover"/>
                     ) : <div className="w-10 h-10 bg-secondary rounded-md"></div>}
                     {p.name}
                   </td>
                   <td className="p-4 ">{p.category}</td>
                   <td className="p-4">
                     ${p.price.toFixed(2)}
                     {p.discountPrice && <span className="text-destructive ml-2 text-sm">${p.discountPrice.toFixed(2)}</span>}
                   </td>
                   <td className="p-4 flex gap-2 justify-end">
                      <button onClick={() => handleEdit(p)} className="p-2 text-blue-500 hover:bg-blue-500/10 rounded-lg transition-colors"><Edit className="w-4 h-4"/></button>
                      <button onClick={() => handleDelete(p._id)} className="p-2 text-destructive hover:bg-destructive/10 rounded-lg transition-colors"><Trash2 className="w-4 h-4"/></button>
                   </td>
                 </tr>
               ))}
               {products.length === 0 && (
                 <tr><td colSpan="4" className="p-8 text-center text-muted-foreground">No products found. Add one above.</td></tr>
               )}
             </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

'use client'
import { useStore } from '@/lib/store'
import Link from 'next/link'
import { Trash2, ArrowRight, Package2 } from 'lucide-react'
import { useState } from 'react'
import { useRouter } from 'next/navigation'

export default function CartPage() {
  const { cart, user, setCart, removeFromCartMock } = useStore()
  const [loadingId, setLoadingId] = useState(null)
  const router = useRouter()

  const items = cart?.items || []

  const handleRemove = async (productId) => {
    if (!user) {
      removeFromCartMock(productId)
      return
    }
    setLoadingId(productId)
    try {
      const res = await fetch(`/api/cart?productId=${productId}`, { method: 'DELETE' })
      if (res.ok) {
        const updated = await res.json()
        setCart(updated)
      }
    } catch(err) {
      console.error(err)
    } finally {
      setLoadingId(null)
    }
  }

  const subtotal = items.reduce((acc, item) => {
    const price = item.productId.discountPrice || item.productId.price || 0
    return acc + price * item.quantity
  }, 0)

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-32 text-center animate-in fade-in duration-500">
        <div className="w-24 h-24 bg-secondary rounded-full flex items-center justify-center mb-6">
          <Package2 className="w-10 h-10 text-muted-foreground"/>
        </div>
        <h1 className="text-3xl font-bold mb-4">Your cart is empty</h1>
        <p className="text-muted-foreground mb-8 text-lg">Looks like you haven't added anything to your cart yet.</p>
        <Link href="/products" className="bg-primary text-primary-foreground px-8 py-4 rounded-full font-bold hover:bg-primary/90 transition-all shadow-xl flex items-center gap-2">
          Start Shopping <ArrowRight className="w-4 h-4"/>
        </Link>
      </div>
    )
  }

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 pb-12">
      <h1 className="text-4xl font-extrabold tracking-tight mb-8">Shopping Cart</h1>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        <div className="lg:col-span-2 space-y-6">
          {items.map((item) => {
             const product = item.productId
             const price = product.discountPrice || product.price
             return (
              <div key={product._id} className="flex gap-6 items-center p-4 md:p-6 bg-card border rounded-3xl shadow-sm relative pr-12 md:pr-6">
                <div className="w-24 h-24 md:w-32 md:h-32 bg-secondary rounded-2xl overflow-hidden shadow-inner flex-shrink-0 relative">
                  {product.imageUrl ? (
                     <img src={product.imageUrl} alt={product.name} className="object-cover w-full h-full" />
                  ) : (
                     <div className="w-full h-full flex items-center justify-center text-xs text-muted-foreground uppercase">Luxe</div>
                  )}
                </div>
                <div className="flex-1 space-y-1 md:space-y-2">
                  <div className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">{product.category}</div>
                  <Link href={`/product/${product._id}`} className="font-bold text-lg hover:text-primary transition-colors block line-clamp-1">{product.name}</Link>
                  <div className="text-primary font-black">${price?.toFixed(2)}</div>
                  <div className="text-sm text-muted-foreground">Qty: {item.quantity}</div>
                </div>
                <button 
                  disabled={loadingId === product._id}
                  onClick={() => handleRemove(product._id)}
                  className="absolute top-4 right-4 md:relative md:top-0 md:right-0 p-2 md:p-3 bg-destructive/10 text-destructive rounded-full hover:bg-destructive hover:text-destructive-foreground transition-all ml-auto disabled:opacity-50"
                >
                  <Trash2 className="w-4 h-4 md:w-5 md:h-5"/>
                </button>
              </div>
             )
          })}
        </div>

        <div>
          <div className="glass p-6 md:p-8 rounded-3xl sticky top-24 space-y-6">
            <h2 className="text-2xl font-bold border-b border-border/50 pb-4">Order Summary</h2>
            <div className="space-y-3 text-lg">
              <div className="flex justify-between text-muted-foreground">
                <span>Subtotal</span>
                <span>${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-muted-foreground">
                <span>Shipping</span>
                <span>{subtotal > 100 ? 'Free' : '$10.00'}</span>
              </div>
            </div>
            <div className="flex justify-between font-black text-2xl pt-4 border-t border-border/50">
                <span>Total</span>
                <span>${(subtotal > 100 ? subtotal : subtotal + 10).toFixed(2)}</span>
            </div>

            <button 
              onClick={() => {
                if(!user) {
                  router.push('/login?redirect=/checkout')
                } else {
                  router.push('/checkout')
                }
              }}
              className="w-full bg-primary text-primary-foreground py-4 rounded-full font-bold text-lg hover:bg-primary/90 transition-all shadow-lg hover:-translate-y-0.5 flex justify-center items-center gap-2 mt-4"
            >
              Proceed to Checkout <ArrowRight className="w-5 h-5"/>
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'
import { useState } from 'react'
import { useStore } from '@/lib/store'
import { useRouter, useSearchParams } from 'next/navigation'
import Link from 'next/link'

export default function LoginPage() {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const { setUser, setCart } = useStore()
  const router = useRouter()

  const handleSubmit = async (e) => {
    e.preventDefault()
    setLoading(true)
    setError('')
    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      })
      const data = await res.json()

      if (res.ok) {
        setUser(data.user)
        // fetch cart
        const cartRes = await fetch('/api/cart')
        const cartData = await cartRes.json()
        setCart(cartData)

        router.push(data.user.role === 'admin' ? '/admin' : '/')
      } else {
        setError(data.error || 'Login failed')
      }
    } catch(err) {
      setError('An error occurred. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] animate-in fade-in duration-500">
      <div className="w-full max-w-md p-8 glass rounded-3xl shadow-2xl border border-border/50 bg-card">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold tracking-tight">Welcome Back</h1>
          <p className="text-muted-foreground mt-2">Enter your details to access your account</p>
        </div>

        {error && <div className="bg-destructive/10 text-destructive p-3 rounded-lg text-sm mb-6 font-medium text-center">{error}</div>}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-semibold">Email</label>
            <input 
              type="email" 
              required 
              value={email}
              onChange={e => setEmail(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-border bg-background focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all"
              placeholder="you@example.com"
            />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold">Password</label>
            <input 
              type="password" 
              required 
              value={password}
              onChange={e => setPassword(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-border bg-background focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all"
              placeholder="••••••••"
            />
          </div>
          <button 
            type="submit" 
            disabled={loading}
            className={`w-full bg-primary text-primary-foreground py-3.5 rounded-xl font-bold mt-4 shadow-md hover:-translate-y-0.5 transition-all ${loading ? 'opacity-70' : ''}`}
          >
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>

        <p className="text-center mt-8 text-sm text-muted-foreground">
          Don't have an account? <Link href="/register" className="text-primary font-bold hover:underline">Sign up</Link>
        </p>
      </div>
    </div>
  )
}

import dbConnect from "@/lib/mongodb"
import Product from "@/models/Product"
import Link from "next/link"
import { Tag } from "lucide-react"

export const dynamic = 'force-dynamic'

async function getProducts() {
  await dbConnect()
  const products = await Product.find({}).sort({ createdAt: -1 })
  return JSON.parse(JSON.stringify(products))
}

export default async function ProductsPage() {
  const products = await getProducts()

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-12">
      <div className="flex flex-col gap-2">
        <h1 className="text-4xl font-extrabold tracking-tight">The Collection</h1>
        <p className="text-muted-foreground text-lg">Detailed aesthetics for the modern minimalist.</p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6 lg:gap-8">
        {products.map(product => (
          <Link href={`/product/${product._id}`} key={product._id} className="group flex flex-col gap-3 cursor-pointer">
            <div className="relative aspect-[4/5] rounded-3xl bg-secondary/50 overflow-hidden border border-border/50 shadow-sm group-hover:shadow-xl transition-shadow duration-500">
              {product.discountPrice && (
                <div className="absolute top-3 left-3 z-10 bg-destructive text-destructive-foreground text-xs font-bold px-2 py-1 rounded-full flex items-center gap-1 shadow-sm">
                  <Tag className="w-3 h-3"/> 
                  -{Math.round((1 - product.discountPrice / product.price) * 100)}%
                </div>
              )}
              {product.imageUrl ? (
                <img src={product.imageUrl} alt={product.name} className="object-cover w-full h-full group-hover:scale-105 transition-transform duration-700 ease-out" />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-muted-foreground group-hover:scale-105 transition-transform duration-700 bg-gradient-to-br from-secondary to-background">
                  <span className="text-2xl font-light uppercase tracking-widest text-primary/40">Luxe</span>
                </div>
              )}
            </div>
            <div className="px-1">
              <div className="text-xs text-muted-foreground uppercase tracking-widest font-semibold mb-1">{product.category}</div>
              <h3 className="font-semibold text-lg line-clamp-1 group-hover:text-primary transition-colors">{product.name}</h3>
              <div className="flex items-center gap-2 mt-1">
                {product.discountPrice ? (
                  <>
                    <span className="font-bold text-lg text-foreground">${product.discountPrice.toFixed(2)}</span>
                    <span className="text-sm text-muted-foreground line-through">${product.price.toFixed(2)}</span>
                  </>
                ) : (
                  <span className="font-bold text-lg text-foreground">${product.price.toFixed(2)}</span>
                )}
              </div>
            </div>
          </Link>
        ))}

        {products.length === 0 && (
          <div className="col-span-full py-20 text-center border-2 border-dashed rounded-3xl text-muted-foreground">
             <p>No products yet. Stay tuned!</p>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'
import Link from 'next/link'
import { ShoppingCart, User, LogOut, Package2, Shield } from 'lucide-react'
import { useStore } from '@/lib/store'
import { useEffect, useState } from 'react'

export default function Navbar() {
  const { user, cart, logout, setUser, setCart } = useStore()
  const [mounted, setMounted] = useState(false)

  // Hydration fix & fetch session
  useEffect(() => {
    setMounted(true)
    const fetchSession = async () => {
      try {
        const res = await fetch('/api/auth/me')
        const data = await res.json()
        if (data.user) {
          setUser(data.user)
          // Also fetch cart
          const cartRes = await fetch('/api/cart')
          const cartData = await cartRes.json()
          setCart(cartData)
        }
      } catch (err) {
        console.error(err)
      }
    }
    fetchSession()
  }, [])

  const handleLogout = async () => {
    await fetch('/api/auth/logout', { method: 'POST' })
    logout()
  }

  const cartCount = cart?.items?.reduce((acc, item) => acc + item.quantity, 0) || 0

  if (!mounted) return null // avoid hydration mismatch

  return (
    <nav className="glass sticky top-0 z-50 p-4 shadow-sm border-b border-border/40">
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <Link href="/" className="font-bold text-2xl tracking-tighter flex items-center gap-2">
          <div className="bg-primary text-primary-foreground p-1.5 rounded-lg">
            <Package2 className="w-5 h-5"/>
          </div>
          Luxe<span className="text-primary">Shop</span>
        </Link>
        <div className="flex items-center gap-6">
          <Link href="/products" className="text-sm font-medium hover:text-primary transition-colors">
            Shop
          </Link>

          {user ? (
            <>
              {user.role === 'admin' && (
                <Link href="/admin" className="text-sm font-medium flex items-center gap-1 hover:text-primary transition-colors">
                  <Shield className="w-4 h-4"/> Admin
                </Link>
              )}
              <Link href="/orders" className="text-sm font-medium hover:text-primary transition-colors">
                Orders
              </Link>
              <button onClick={handleLogout} className="text-sm font-medium hover:text-destructive transition-colors flex items-center gap-1">
                <LogOut className="w-4 h-4"/> Logout
              </button>
            </>
          ) : (
            <Link href="/login" className="text-sm font-medium hover:text-primary transition-colors flex items-center gap-1">
              <User className="w-4 h-4"/> Login
            </Link>
          )}

          <Link href="/cart" className="relative p-2 hover:bg-secondary rounded-full transition-colors flex items-center justify-center">
            <ShoppingCart className="w-5 h-5" />
            {cartCount > 0 && (
              <span className="absolute top-0 right-0 bg-primary text-primary-foreground text-[10px] font-bold px-1.5 py-0.5 rounded-full min-w-[20px] text-center transform translate-x-1/4 -translate-y-1/4">
                {cartCount}
              </span>
            )}
          </Link>
        </div>
      </div>
    </nav>
  )
}
